INFO = {}


def ur_list(path):
    """2026年3月の売上明細の一覧（システムからの出力）。売上明細（Excel）の3月分と同じ内容"""
    ws = load_workbook(f'{ROOT}/out/{R["src"]}/B_対照版/共通資料/売上明細_2025年度.xlsx', read_only=True).worksheets[0]
    rows = [[r[0], r[1], r[2], sd(r[3]), r[4], r[5], r[6], yen(r[8]), yen(r[9]), yen(r[10]), r[11] or '', r[12] or ''] for r in ws.iter_rows(min_row=2, values_only=True) if (r[3].year, r[3].month) == (2026, 3)]
    tot = sum(r[10] for r in ws.iter_rows(min_row=2, values_only=True) if (r[3].year, r[3].month) == (2026, 3))
    g = table_print(path, 'S0310 売上明細一覧　対象：2026/03/01〜2026/03/31（売上計上日）　出力日時 2026/04/09 08:52　出力者 宮下',
                    [('売上番号', 25, 'c'), ('行', 7, 'c'), ('区分', 12, 'c'), ('売上計上日', 20, 'c'), ('コード', 14, 'c'), ('取引先名', 58, 'l'), ('品番', 28, 'l'), ('数量', 14, 'r'), ('単価', 18, 'r'), ('金額（税抜）', 24, 'r'), ('受注番号', 26, 'c'), ('出荷番号', 26, 'c')], rows,
                    foot=f'合計 {len(rows):,} 行　金額合計 {tot:,} 円（取消を含む）')
    INFO['pages'] = g.pno + 1
    return g


